-- B9 c2 — Seed fund_descriptions with SEC-filed verbatim text (23 funds)
-- Source: SEC Mutual Fund Prospectus Risk/Return Summary Data Sets (XBRL),
-- quarters 2025q3–2026q2, latest filing per fund. The text is the fund's own
-- filed language: HTML removed, paragraph breaks preserved, no word changed.
-- Punctuation restoration (Robert's ruling, July 31, 2026): the SEC dataset
-- flattening drops typographic apostrophes; 40 possessive apostrophes were
-- restored across 16 funds, each listed in B9_RESTORATION_LEDGER.md, and the
-- operator verifies each fund's box against its linked EDGAR filing.
-- Run AFTER b9_fund_descriptions.sql. Idempotent: ON CONFLICT replaces rows.

-- ADAXX: accession 0001104659-26-077782, series S000000253, prospectus date 2026-06-30
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Fund’s investment objective is to provide current income consistent with preservation of capital and liquidity.', 'The Fund invests at least 99.5% of its total assets in cash, government securities, and repurchase agreements collateralized by cash or government securities. In addition, at least 80% of the Fund’s net assets (plus any borrowings for investment purposes) will be invested, under normal circumstances, in government securities and/or repurchase agreements that are collateralized by government securities. In contrast to the Funds 99.5% investment policy, the Funds 80% investment policy does not include cash or repurchase agreements collateralized by cash. For purposes of the foregoing investment policies, a government security generally means any security issued or guaranteed as to principal or interest by the United States, or by a person controlled or supervised by and acting as an instrumentality of the government of the United States. The Fund is a Government Money Market Fund, as defined by Rule 2a-7 under the Investment Company Act of 1940, as amended (Rule 2a-7), that seeks to maintain a stable price of $1.00 per share by using the amortized cost method to value portfolio securities and rounding the share value to the nearest cent. The Fund invests in conformity with SEC rules and regulation requirements for money market funds for the quality, maturity, diversification and liquidity of investments. The Fund invests only in U.S. dollar-denominated securities maturing within 397 calendar days of the date of purchase, with certain exceptions permitted by applicable regulations. The Fund maintains a dollar-weighted average portfolio maturity of no more than 60 calendar days, and a dollar-weighted average life to maturity of portfolio securities of not more than 120 calendar days (determined without reference to exceptions regarding interest rate adjustments). The Fund will limit investments to those securities that are Eligible Securities as defined by applicable regulations at the time of purchase. Eligible Securities are (i) government securities, (ii) shares of other money market funds, and (iii) securities determined to present minimal credit risks by Invesco Advisers, Inc. (Invesco or the Adviser) pursuant to guidelines approved by the Fund''s Board of Trustees (the Board). In selecting securities for the Fund’s portfolio, the portfolio managers focus on securities that offer safety, liquidity, and a competitive yield. The portfolio managers normally hold portfolio securities to maturity, but may sell a particular security when they deem it advisable, such as when market or credit factors materially change.', '0001104659-26-077782', 'S000000253', '2026-06-30'
FROM funds WHERE ticker = 'ADAXX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- BGHIX: accession 0001193125-26-176472, series S000071892, prospectus date 2025-12-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The funds objective is high current income with the opportunity for capital appreciation.', 'Under normal market conditions, the fund intends to provide exposure to high yield securities by investing at least 80% of its net assets in a diversified portfolio of corporate debt securities that are rated at the time of purchase below investment grade (that is, securities rated below Baa/BBB assigned by at least one Nationally Recognized Statistical Rating Organization (NRSRO)) or unrated securities determined by the subadviser to be of comparable credit quality. These investments are also known as junk bonds, high yield bonds, and non-investment grade bonds, and may include so called distressed debt. Such securities may be public or privately placed U.S. dollar denominated debt securities issued by U.S. and non-U.S. companies (which may include companies in emerging markets) of any size, which the subadviser believes represent an attractive investment opportunity. However, investments in non-U.S. obligations or securities will not exceed 25% of the net assets of the fund. The fund also may invest in other securities including investment grade securities. The fund may invest in securities of any maturity and does not maintain a dollar-weighted effective duration target for the securities in which it invests. While not a part of the funds principal investment strategy of investing in corporate bonds, the fund may invest in other securities such as trust preferred securities, convertible securities, preferred stock, equity securities, U.S. Government and Agency securities, and mortgage or asset-backed securities. In selecting securities for the fund, the subadviser performs a risk/reward analysis that includes an evaluation of credit risk, interest rate risk, yield and the legal and technical structure of the security. The subadviser will attempt to take advantage of inefficiencies that it believes exist in the fixed-income markets by purchasing securities at prices below the subadviser’s estimate of their fair value with the goal of selling securities as they approach or exceed the subadviser’s estimate of their fair value. The subadviser seeks to invest in securities that the subadviser expects to offer attractive prospects for current income and/or capital appreciation in relation to the risk borne.', '0001193125-26-176472', 'S000071892', '2025-12-31'
FROM funds WHERE ticker = 'BGHIX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- BPLBX: accession 0001193125-26-181806, series S000062365, prospectus date 2025-12-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The investment objective of the BlackRock Inflation Protected Bond Portfolio (the Inflation Protected Bond Portfolio or the Fund) is to seek to maximize real return, consistent with preservation of real capital and prudent investment management.', 'Under normal circumstances, the Fund invests at least 80% of its net assets, plus the amount of borrowings for investment purposes in inflation-indexed bonds of varying maturities issued by the U.S. and non-U.S. governments, their agencies or instrumentalities, and U.S. and non-U.S. corporations. Investments in derivatives are counted toward the Funds 80% policy to the extent that they provide investment exposure to the securities included within that policy or to one or more market risk factors associated with such securities. The Fund maintains an average portfolio duration that is within 40% of the duration of the Bloomberg U.S. Treasury Inflation Protected Securities Index (the benchmark). The Fund may invest up to 20% of its assets in non-investment grade bonds (high yield or junk bonds) or securities of emerging market issuers. The Fund may also invest up to 20% of its assets in non-dollar denominated securities of non-U.S. issuers, and may invest without limit in U.S. dollar denominated securities of non-U.S. issuers. The Fund may seek to provide exposure to the investment returns of real assets that trade in the commodity markets through investment in commodity-linked derivative instruments and investment vehicles such as exchange-traded funds that exclusively invest in commodities and are designed to provide this exposure without direct investment in physical commodities. The Fund may also gain exposure to commodity markets by investing up to 25% of its total assets in Cayman Inflation Protected Bond Portfolio, Ltd. (the Subsidiary ), a wholly owned subsidiary of the Fund formed in the Cayman Islands, which invests primarily in commodity-related instruments. The Fund also makes investments in residential and commercial mortgage-backed securities and other asset-backed securities. Non-investment grade bonds acquired by the Fund will generally be in the lower rating categories of the major rating agencies (BB or lower by S&P Global Ratings (S&P) or Ba or lower by Moodys Investors Service, Inc. (Moodys)) or will be determined by the management team to be of similar quality. Split rated bonds will be considered to have the higher credit rating. Split rated bonds are bonds that receive different ratings from two or more rating agencies. The Fund may buy or sell options or futures, or enter into credit default swaps and interest rate or foreign currency transactions, including swaps (collectively, commonly known as derivatives). The Fund may seek to obtain market exposure to the securities in which it primarily invests by entering into a series of purchase and sale contracts or by using other investment techniques (such as reverse repurchase agreements or dollar rolls). The Fund may engage in active and frequent trading of portfolio securities to achieve its primary investment strategies.', '0001193125-26-181806', 'S000062365', '2025-12-31'
FROM funds WHERE ticker = 'BPLBX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- CEMEX: accession 0001999371-25-016327, series S000038162, prospectus date 2025-10-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Cullen Emerging Markets High Dividend Fund (the Emerging Markets High Dividend Fund or the Fund) seeks current income and long-term capital appreciation.', 'The Emerging Markets High Dividend Fund invests, under normal circumstances, at least 80% of its net assets, plus borrowings for investment purposes, in high dividend paying securities of companies across all capitalizations that are organized in, maintain at least 50% of their assets in, or derive at least 50% of their revenues from, emerging market countries. As a point of comparison, a high dividend paying common stock that the Emerging Markets High Dividend Fund would invest in would generally have a dividend yield greater than the average dividend yield of the equity securities in the MSCI Emerging Markets Index. An emerging market country is any country that has been determined by an international organization, such as the World Bank, to have a relatively low to middle income economy. In selecting stocks, the Emerging Markets High Dividend Fund’s portfolio managers select companies that have growth potential, focusing on companies across all capitalizations. The Fund’s holdings may include issues denominated in currencies of emerging countries, investment companies (like country funds) which invest in emerging countries, American Depositary Receipts (ADRs), European Depositary Receipts (EDRs), Global Depositary Receipts (GDRs) and other similar instruments (ADRs, EDRs and GDRs are hereinafter collectively referred to as depositary receipts), and similar types of investments representing emerging markets securities. Depositary receipts may be purchased through sponsored or unsponsored facilities. A sponsored facility is established jointly by the issuer of the underlying security and a depositary, whereas a depositary may establish an unsponsored facility without participation by the issuer of the depositary security. Holders of unsponsored depositary receipts generally bear all the costs of such facilities and the depositary of an unsponsored facility frequently is under no obligation to distribute shareholder communications received from the issuer of the deposited security or to pass through voting rights to the holders of such receipts. The Emerging Markets High Dividend Fund intends to diversify its investments across different countries, and the percentage of the Emerging Markets High Dividend Funds assets invested in particular countries or regions will change from time to time based on the Adviser’s judgment. However, the Fund will not have more than 30% of its total assets invested as at the time of purchase in securities of any one country. The Emerging Markets High Dividend Fund generally invests substantially all of its assets in common stocks and depositary receipts but can invest in other equity securities, which can include convertible debt, exchange-traded funds (ETFs) that invest primarily in equity securities, warrants, rights, equity interests in real estate investment trusts (REITs), equity interests in master limited partnerships (MLPs), and preferred stocks. The Emerging Markets High Dividend Fund invests roughly the same amount of its assets in each position in the portfolio at the time of original purchase, although the portfolio is not systematically rebalanced. This approach avoids the overweighting of any individual security being purchased. The Adviser may sell portfolio stocks when they are no longer attractive based on their growth potential, dividend yield or price. As part of its strategy, the Emerging Markets High Dividend Fund, in order to generate additional income, may selectively write covered call options when it is deemed to be in the Fund’s best interest. A call option is a short-term contract entitling the purchaser, in return for a premium paid, the right to buy the underlying equity security at a specified price upon exercise of the option at any time prior to its expiration. Writing a covered call option allows the Emerging Markets High Dividend Fund to receive a premium. A call option gives the holder the right, but not the obligation, to buy the underlying equity stock from the writer of the option at a given price during a specific period. The Emerging Markets High Dividend Fund will not engage in derivatives except to the extent that either (1) the writing of covered call options, and or (2) participatory notes, is deemed to involve derivatives.', '0001999371-25-016327', 'S000038162', '2025-10-31'
FROM funds WHERE ticker = 'CEMEX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- CFSTX: accession 0001193125-26-075252, series S000010031, prospectus date 2025-10-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The investment objective of the Fund is to seek current income with preservation of principal.', 'Security Types: Under normal market conditions, the Fund invests at least 80% of its net assets plus any borrowings for investment purposes (measured at the time of purchase) in securities issued or guaranteed by the U.S. Government, its agencies or instrumentalities (including U.S. Treasury bills, notes, bonds and inflation-protected obligations) and government mortgage-backed securities (pools of mortgage loans sold to investors by various governmental agencies). The Fund may also purchase other mortgage-backed and asset-backed securities, which are sold by private issuers. The Fund will provide shareholders with at least 60 days notice before changing its 80% investment policy. Credit Quality: The Fund invests primarily in securities rated investment grade (AAA, AA, A, BBB or an equivalent rating) by one of the major credit rating agencies (S&P Global Ratings, Moodys and Fitch) that has assigned a rating to the security or, if unrated, deemed to be investment-grade quality by the Adviser. Maturity Distribution: The Fund emphasizes purchasing short-term bonds. The Fund invests at least 65% of its total assets in securities issued or guaranteed by the U.S. Government, its agencies or instrumentalities and government mortgage-backed securities that have average lives or remaining maturities of five years or less. The Fund actively manages maturities to take advantage of changes in interest rates. The dollar-weighted average maturity of the Fund’s investments will not exceed three years.', '0001193125-26-075252', 'S000010031', '2025-10-31'
FROM funds WHERE ticker = 'CFSTX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- DRRYX: accession 0000030146-26-000070, series S000028808, prospectus date 2025-10-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The fund seeks total return (consisting of capital appreciation and income).', 'To pursue its goal, the fund uses an actively-managed multi-asset strategy to seek to produce absolute or real returns with less volatility than major equity markets over a complete market cycle, typically a period of five years. The fund is not managed to a benchmark index. Rather than managing to track a benchmark index, the fund seeks to provide returns that are largely independent of market moves. The fund allocates its investments among global equities, bonds and cash, and, generally to a lesser extent, other asset classes, including real estate, commodities, currencies and alternative or non-traditional asset classes and strategies, primarily those accessed through derivative instruments. The fund may invest in, or otherwise have investment exposure to, the securities of companies of any market capitalization. The fund obtains investment exposure to these asset classes by investing in securities and through derivative instruments. The fund''s sub-adviser, Newton Investment Management Limited, an affiliate of BNY Mellon Investment Adviser, Inc., combines a top-down approach, emphasizing economic trends and current investment themes on a global basis, with bottom-up security selection based on fundamental research to allocate the fund''s investments among and within asset classes. In choosing investments, the sub-adviser considers: key trends in global economic variables, such as gross domestic product, inflation and interest rates; investment themes, such as changing demographics, the impact of new technologies and the globalization of industries and brands; relative valuations of equity securities, bonds and cash; long-term trends in currency movements; and company fundamentals. Within markets and sectors determined to be attractive in absolute terms, the fund''s sub-adviser seeks what it believes to be attractively priced companies that possess a sustainable competitive advantage in their market or sector and invests in such companies across their capital structures. The fund generally will sell investments when themes change or when the sub-adviser determines that a particular market or sector is no longer considered attractive in absolute terms, a company''s prospects have changed or the investment is fully valued by the market. The fund''s investments will be focused globally among the developed and emerging capital markets of the world. Under normal market conditions, the fund will invest a substantial portion of its assets in the securities of issuers organized or located outside the United States, whose primary listing exchange for securities is located outside the United States, whose largest amount of revenues are derived from countries outside the United States or whose reporting currencies are other than U.S. dollars, and derivatives which provide exposure to such issuers or foreign markets. The fund may, from time to time, invest a significant portion (more than 20%) of its net assets in securities of companies in certain countries. The sub-adviser has considerable latitude in allocating the fund''s investments and in selecting securities and derivative instruments to implement the fund''s investment approach, although the fund must invest at least 10% of the value of its total assets in equity securities and at least 10% of the value of its total assets in fixed-income securities. The fund may invest in bonds and other fixed-income securities of any maturity or duration. The fund may gain exposure to equity or fixed-income securities by investing in investment companies, including exchange-traded funds (ETFs) and investment trusts whose shares typically are traded on a foreign exchange. The fund will use, to a significant degree, derivative instruments as a substitute for investing directly in equities, bonds, currencies and other asset classes in connection with its investment strategy. The fund also may use derivative instruments as part of a hedging strategy or for other purposes related to the management of the fund. The derivative instruments in which the fund may invest typically include options, futures and options on futures (including those relating to securities, indices, foreign currencies and interest rates), forward contracts, swap agreements and structured notes. The fund also may gain investment exposure to global commodity markets through investments in a wholly-owned and controlled subsidiary of the fund that principally invests directly in commodity-related instruments, including futures and options contracts, swap agreements and pooled investment vehicles that invest in commodities. The subsidiary has the same investment objective, investment adviser and sub-adviser as the fund. The fund''s portfolio will not have the same characteristics as its designated performance baseline benchmark USD 30-day Compounded Secured Overnight Financing Rate (SOFR) or its designated broad-based securities market indices Bloomberg Global Aggregate Index (Hedged) and MSCI World Index. Although the fund is not managed to a benchmark index, the fund seeks to provide a minimum average annual total return of USD 30-day Compounded SOFR plus 4%, before fees and expenses, over a five-year period. There can be no assurance the fund will be able to provide such returns and you may lose money by investing in the fund.', '0000030146-26-000070', 'S000028808', '2025-10-31'
FROM funds WHERE ticker = 'DRRYX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- FDRXX: accession 0000278001-26-000019, series S000007149, prospectus date 2026-01-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Fidelity Government Cash Reserves seeks as high a level of current income as is consistent with the preservation of capital and liquidity.', 'Normally investing at least 99.5% of total assets in cash, U.S. Government securities and/or repurchase agreements that are collateralized fully (i.e., collateralized by cash or government securities). Investing in U.S. Government securities issued by entities that are chartered or sponsored by Congress but whose securities are neither issued nor guaranteed by the U.S. Treasury. Investing in compliance with industry-standard regulatory requirements for money market funds for the quality, maturity, liquidity, and diversification of investments. In addition, the fund normally invests at least 80% of its assets in U.S. Government securities and repurchase agreements for those securities. U.S. Government securities are high-quality securities issued or guaranteed by the U.S. Treasury or by an agency or instrumentality of the U.S. Government. U.S. Government securities may be backed by the full faith and credit of the U.S. Treasury, the right to borrow from the U.S. Treasury, or the agency or instrumentality issuing or guaranteeing the security. Certain issuers of U.S. Government securities, including Fannie Mae, Freddie Mac, and the Federal Home Loan Banks, are sponsored or chartered by Congress but their securities are neither issued nor guaranteed by the U.S. Treasury. The issuer usually pays a fixed, variable, or floating rate of interest, and must repay the amount borrowed, usually at the maturity of the security. A repurchase agreement is an agreement to buy a security at one price and a simultaneous agreement to sell it back at an agreed-upon price. A repurchase agreement entered into by the fund may be collateralized by U.S. Government securities or cash.', '0000278001-26-000019', 'S000007149', '2026-01-31'
FROM funds WHERE ticker = 'FDRXX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- FSPGX: accession 0000035315-26-000387, series S000054095, prospectus date 2026-06-30
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Fidelity Large Cap Growth Index Fund seeks to provide investment results that correspond to the total return of stocks of large capitalization U.S. companies.', '"Normally investing at least 80% of assets in securities included in the Russell 1000 Growth Index. The Russell 1000 Growth Index is a market capitalization-weighted index designed to measure the performance of the large-cap growth segment of the U.S. equity market. It includes those Russell 1000 Index companies with higher price-to-book (P/B) ratios and higher forecasted growth rates. The stocks of these companies are often called ""growth"" stocks. The Russell 1000 Growth Index applies a capping methodology. Index constituents are capped quarterly so that no more than 22.5% of the index weight may be allocated to a single constituent, and the sum of the weights of all constituents representing more than 4.5% of the index should not exceed 45% of the total index weight. Derivative instruments that provide investment exposure to the investments above or exposure to one or more market risk factors associated with such investments are included in the fund''s 80% policy, consistent with the fund''s investment policies and limitations with respect to investments in derivatives. Primarily using replication; however, the fund may or may not hold all of the securities in the index. Lending securities to earn income for the fund. The fund may operate as a non-diversified fund, as defined under the Investment Company Act of 1940 (1940 Act), to the approximate extent the index is non-diversified. The fund may therefore operate as non-diversified solely as a result of a change in relative market capitalization or index weighting of one or more constituents of the index."', '0000035315-26-000387', 'S000054095', '2026-06-30'
FROM funds WHERE ticker = 'FSPGX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- FXAIX: accession 0000819118-26-000072, series S000006027, prospectus date 2026-04-30
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Fidelity 500 Index Fund seeks to provide investment results that correspond to the total return (i.e., the combination of capital changes and income) performance of common stocks publicly traded in the United States.', 'Normally investing at least 80% of assets in common stocks included in the S&P 500 Index. The S&P 500 Index is a market capitalization-weighted index of 500 common stocks that represents the performance of the large-capitalization segment of the U.S. market. Derivative instruments that provide investment exposure to the investments above or exposure to one or more market risk factors associated with such investments are included in the fund''s 80% policy, consistent with the fund''s investment policies and limitations with respect to investments in derivatives. Lending securities to earn income for the fund. The fund may operate as a non-diversified fund, as defined under the Investment Company Act of 1940 (1940 Act), to the approximate extent the index is non-diversified. The fund may therefore operate as non-diversified solely as a result of a change in relative market capitalization or index weighting of one or more constituents of the index.', '0000819118-26-000072', 'S000006027', '2026-04-30'
FROM funds WHERE ticker = 'FXAIX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- HRAUX: accession 0001193125-26-186213, series S000008481, prospectus date 2025-12-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Carillon Eagle Mid Cap Growth Fund (Mid Cap Growth Fund or the fund) seeks long-term capital appreciation.', 'During normal market conditions, the Mid Cap Growth Fund seeks to achieve its objective by investing at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in the equity securities of mid-capitalization companies. The fund’s portfolio managers consider mid-capitalization companies to be those companies that, at the time of initial purchase, have capitalizations greater than $1 billion and equal to or less than the largest company in the Russell Midcap Growth Index during the most recent 12-month period (approximately $300.0 billion during the 12-month period ended December 31, 2025). The fund is not required to sell equity securities whose market values appreciate or depreciate outside this market capitalization range. The fund will invest primarily in the equity securities of companies that the portfolio managers believe have the potential for above-average earnings or sales growth, reasonable valuations and acceptable debt levels. Such stocks can typically have high price-to-earnings ratios. Equity securities include common and preferred stock, warrants or rights exercisable into common or preferred stock and high-quality convertible securities. Although the portfolio managers generally do not emphasize investment in any particular investment sector or industry, the fund may invest a significant portion of its assets in the securities of companies in the information technology, health care and industrials sectors at any given time. The fund will generally sell when the stock has met the portfolio managers’ target price, the investment is no longer valid, a better investment opportunity has arisen or if the investment reaches a value more than 5% of the funds net assets. At times, the fund may hold securities of small-capitalization companies. The fund may lend its securities to broker-dealers and other financial institutions to earn additional income.', '0001193125-26-186213', 'S000008481', '2025-12-31'
FROM funds WHERE ticker = 'HRAUX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- MADFX: accession 0000894189-25-011819, series S000055262, prospectus date 2025-10-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Matrix Advisors Dividend Fund (the Fund) seeks current income and capital appreciation.', 'The Fund invests primarily in dividend-paying common stocks or depositary receipts representing common stocks of U.S. companies and U.S.-listed international companies in developed markets that the Advisor believes pay high and sustainable dividends, are financially strong, and meet specific valuation criteria using the principles of value investing based on Classic Valuation Analysis. Classic Valuation Analysis uses valuation models to analyze statistics such as earnings growth, dividend growth, return on equity and book value versus their historical, current and projected levels to determine a company’s Intrinsic Value. The Advisor seeks securities the price of which is below their Intrinsic Value and the dividend yield of which is above that of the market as represented by the S&P 500 Index. Under normal circumstances, the Fund invests at least 80% of its net assets, plus borrowings for investment purposes, in dividend-paying stocks. Dividend-paying stocks are those that have declared or paid a dividend distribution within the prior 12-month period. The Fund invests primarily in large capitalization companies, which the Advisor defines as companies with minimum market capitalizations of at least $2 billion at the time of purchase. Stocks are a candidate for sale when their dividend yield falls near or below that of the market as represented by the S&P 500 Index, there has been a significant decline in the strength of the issuer’s balance sheet or operating results, if a security needs to be sold to fund the purchase of a more attractive security with a higher dividend yield, or when the Advisor believes the market price of a security is no longer attractive compared to its Intrinsic Value. The Fund may invest in any sector. At times, the Advisor may overweight or underweight the Fund’s portfolio in one or more particular sectors.', '0000894189-25-011819', 'S000055262', '2025-10-31'
FROM funds WHERE ticker = 'MADFX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- MWTSX: accession 0001193125-25-186405, series S000001147, prospectus date 2025-03-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Total Return Bond Fund seeks to maximize long-term total return.', 'The Fund pursues its objective by investing, under normal circumstances, at least 80% of its net assets in investment grade fixed income securities or unrated securities determined by the Adviser to be of comparable quality. Up to 20% of the Fund’s net assets may be invested in securities rated below investment grade (commonly known as junk bonds) or unrated securities determined by the Adviser to be of comparable quality. The Fund also invests, under normal circumstances, at least 80% of its net assets, plus any borrowings for investment purposes, in fixed income securities it regards as bonds. A bond is a security or instrument having one or more of the following characteristics: a fixed-income security, a security issued at a discount to its face value, a security that pays interest or a security with a stated principal amount that requires repayment of some or all of that principal amount to the holder of the security. The term bond is interpreted broadly by the Adviser as an instrument or security evidencing a promise to pay some amount rather than evidencing the corporate ownership of equity, unless that equity represents an indirect or derivative interest in one or more bonds. Under normal circumstances, the Fund’s portfolio duration is two to eight years and the Fund’s dollar-weighted average maturity ranges from two to fifteen years. Duration is a measure of the expected life of a fixed income security that is used to determine the sensitivity of a security to changes in interest rates. The Fund invests in the U.S. and abroad, including emerging markets, and may purchase securities of varying maturities issued by domestic and foreign corporations and governments. The Fund may invest up to 25% of its assets in foreign securities that are denominated in U.S. dollars. The Fund may invest up to 15% of its assets in securities of foreign issuers that are not denominated in U.S. dollars. The Fund may invest up to 10% of its assets in emerging market securities. The Adviser focuses the Fund’s portfolio holdings in areas of the bond market that the Adviser believes to be relatively undervalued, based on its analysis of quality, sector, coupon or maturity, and that the Adviser believes offer attractive prospective risk-adjusted returns compared to other segments of the bond market. The Fund’s investments include various types of bonds and debt securities, including corporate bonds, notes, mortgage-related and asset-backed securities (including collateralized debt obligations, which in turn include collateralized bond obligations and collateralized loan obligations), bank loans, U.S. and non-U.S. money market securities, municipal securities, derivatives including credit default swaps and other swaps, futures, options and currency forward contracts, defaulted debt securities, private placements and restricted securities. The Fund’s fixed income investments may have interest rates that are fixed, variable or floating. Derivatives are used in an effort to hedge investments, for risk management, or to increase income or gains for the Fund. The Fund may also seek to obtain market exposure to the securities in which it invests by entering into a series of purchase and sale contracts or by using other investment techniques. The Fund may engage in active and frequent trading of portfolio securities to achieve its primary investment strategies. The Fund may normally short sell up to 25% of the value of its total assets.', '0001193125-25-186405', 'S000001147', '2025-03-31'
FROM funds WHERE ticker = 'MWTSX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- OIBIX: accession 0001104659-26-078660, series S000064709, prospectus date 2026-06-30
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Fund’s investment objective is to seek total return.', '1. The following information replaces the seventh paragraph appearing under the heading Principal Investment Strategies of the Fund in the prospectuses: The Fund may invest up to 25% of its total assets in a Cayman Islands exempted company that is wholly-owned and controlled by the Fund (the Subsidiary). The Subsidiary invests in commodity-linked derivatives (including commodity futures, financial futures, options and swap contracts), commodity-linked notes and in Regulation S securities. Regulation S securities are securities of U.S. and non-U.S. issuers that are issued through private offerings without registration with the Securities and Exchange Commission pursuant to Regulation S under the Securities Act. The Subsidiary may also invest in certain fixed-income securities and other investments that may serve as margin or collateral for its derivatives positions. The Fund applies its investment restrictions and compliance policies and procedures, on a look-through basis, to the Subsidiary. Since the Fund may invest a substantial portion of its assets in the Subsidiary, which may hold certain of the investments described in this prospectus, the Fund may be considered to be investing indirectly in those investments through its Subsidiary. Therefore, references in this prospectus to investments by the Fund also may be deemed to include the Fund''s indirect investments through the Subsidiary.', '0001104659-26-078660', 'S000064709', '2026-06-30'
FROM funds WHERE ticker = 'OIBIX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- PRPFX: accession 0001193125-26-250592, series S000006016, prospectus date 2026-01-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Permanent Portfolio seeks to preserve and increase the purchasing power value of its shares over the long term.', 'In pursuit of its investment objective, the Portfolios strategy is to invest a fixed Target Percentage of its net assets in each of the following investment categories: Investment Category Target Percentage Gold 20% Silver 5% Swiss franc assets 10% Real estate and natural resource stocks 15% Aggressive growth stocks 15% Dollar assets 35% Total 100% These Target Percentages are fundamental and cannot be changed without shareholder approval. Because investment prices are constantly changing, the Portfolios holdings are not expected to match exactly the Target Percentages. Ordinarily, whenever the Portfolios holdings in an investment category deviate from the categorys Target Percentage by more than one-quarter of the Target Percentage, the Portfolio will buy or sell investments to bring investments back within range (unless the discrepancy is corrected by changes in market prices) and will do so within ninety days. However, the Portfolios investment adviser may delay making portfolio adjustments if in its view, circumstances, including a disorderly market or adverse tax consequences, make it desirable to do so. The investment adviser does not attempt to anticipate short-term changes in the general price level of any investment category. The Portfolios investments in: Gold ??consists of gold bullion and bullion-type coins; Silver ??consists of silver bullion and bullion-type coins; Swiss franc assets ??consist of demand deposits of Swiss francs at Swiss or non-Swiss banks and highly rated bonds, as defined below, and other securities of the federal government of Switzerland of any maturity; Real estate and natural resource stocks ??include stocks (including common and preferred shares, and depository receipts such as American Depositary Receipts (ADRs)) of U.S. and foreign companies whose assets consist primarily of real estate (such as timberland, ranching and farm land, raw land, land with improvements and structures and real estate investment trusts (REITs)) and natural resources (such as companies involved directly or indirectly in exploring, mining, refining, processing, transporting, fabricating and dealing in oil, gas, coal and precious and non-precious minerals); Aggressive growth stocks ??include stocks and stock warrants of U.S. and foreign companies that are expected to have a higher profit potential than the stock market as a whole and whose shares are valued primarily for potential growth in revenues, earnings, dividends or asset values rather than for current income. Such companies may include those involved in technology, medicine, capital goods, construction, transportation, finance, entertainment or service, those developing or exploiting new industries, products, services or markets, or those whose shares are otherwise undervalued. The price volatility of such investments is expected to be greater than the price volatility of the U.S. stock market as a whole; and Dollar assets ??include cash, U.S. Treasury bills, notes and bonds, and other U.S. dollar-denominated assets such as the obligations of U.S. government agencies, bankers acceptances and other bank obligations, commercial paper, and corporate bonds and other fixed income obligations of U.S. and non-U.S. issuers. The Portfolio is non-diversified and thus is able to invest more of its assets in fewer issuers and types of investments (e.g., gold and silver) than a diversified fund. The Portfolio may invest in shares of companies of any market capitalization, including small-, mid- and large- capitalization companies. Within its aggressive growth stocks investment category, the Portfolio expects to hold stocks of issuers from at least twelve different industry groups. The Portfolio may own investments issued by non-U.S. banks and governments and may own stock in non-U.S. companies or investments held outside the United States, including in emerging markets. Corporate bonds and other fixed income obligations in the Portfolios dollar assets investment category, as well as highly rated bonds of the federal government of Switzerland, will, at the time of investment, be rated in the top four rating categories by S&P Global Ratings, a division of S&P Global, Inc. (S&P), rated similarly by another independent rating agency such as Moodys Investors Service, Inc. (Moodys) or Fitch, Inc. (Fitch), or if unrated, determined by the Portfolios investment adviser to be of comparable quality. The Portfolio does not attempt to maintain any pre-set average portfolio maturity or duration in its dollar assets or Swiss franc assets investment categories. The Portfolios strategy of investing a fixed Target Percentage of its net assets in the investment categories listed in the table above reflects the opinion of the Portfolios investment adviser that inflation rates and other economic events cannot be forecast with a high degree of reliability and that only investors who are willing to embrace a high degree of risk should act on such forecasts. The investment strategy of the Portfolio acknowledges a broad range of economic possibilities and incorporates investments for each of them. Viewed in isolation, some of the Portfolios assets, such as gold, silver and stock warrants (in its aggressive growth stocks investment category), would be considered highly speculative. However, the Portfolios investment adviser believes that the various investments are subject to different (and, in some cases, contrary) risks, so that the value of the Portfolios investments in the aggregate may be subject to less risk, over the long term, than the risk associated with any one of the investments taken by itself.', '0001193125-26-250592', 'S000006016', '2026-01-31'
FROM funds WHERE ticker = 'PRPFX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- QFVRX: accession 0001999371-25-010388, series S000009491, prospectus date 2025-07-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Long-term growth of capital and income.', 'Under normal market conditions, Foreign Value Fund invests at least 80 percent of its net assets (plus borrowings for investment purposes) in equity securities issued by foreign markets value issuers. A foreign markets issuer is an issuer operating in any industry sector that derives at least 50 percent of its gross revenues or profits from goods or services produced in non-U.S. markets or from sales made in non-U.S. markets. Issuers in which Foreign Value Fund invests may have any market capitalization. Equity securities include common and preferred shares, warrants and other rights derivative of or convertible into common stocks, American Depositary Receipts (ADRs), and Indian participatory notes (generally an interest in a pool of Indian-listed securities that is traded exclusively outside India by non-Indian registered investors), as well as shares of mutual funds and exchange-traded funds (ETFs), each of which invests at least 80 percent of its net assets in similar securities issued by foreign markets value issuers. To manage Foreign Value Fund’s portfolio, its sub-adviser seeks to identify 50 to 125 value securities, that is, foreign markets securities that the sub-adviser considers as being mispriced by the market but having the best opportunity for price appreciation to reflect their long-term fundamental valuations and/or future cash flows. To select specific investments, the sub-adviser uses a proprietary quantitative investment process focused on bottom-up fundamental research. Foreign Value Fund also may utilize options in an attempt to improve the risk/return profile of Foreign Value Funds returns. Foreign Value Fund also may for hedging purposes buy and sell forward foreign currency exchange contracts in connection with its investments. Generally, Foreign Value Fund invests in foreign markets issuers in Europe, Australia, as well as the larger capital markets of the Far East. Foreign Value Fund, however, also may invest without limit in emerging markets issuers. Foreign Value Fund generally will be invested in issuers in fifteen or more foreign countries and fifteen or more industry sectors. However, Foreign Value Fund may be invested in securities from any country, any industry sector, or of any market capitalization amount.', '0001999371-25-010388', 'S000009491', '2025-07-31'
FROM funds WHERE ticker = 'QFVRX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- RNWGX: accession 0000051931-25-001491, series S000009633, prospectus date 2025-12-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The funds investment objective is long-term capital appreciation.', 'The fund invests primarily in common stocks of companies with significant exposure to developing countries. The securities markets of these countries may be referred to as emerging markets or frontier markets. For purposes of this investment strategy, the fund may invest in equity securities of any company, regardless of where it is domiciled (including developed countries), if the funds investment adviser determines that a significant portion of the company’s assets or revenues (generally 20% or more) is attributable to developing countries. In determining whether a country is a developed country or a developing country for purposes of the funds investment strategy, the funds investment adviser considers such factors as the countrys per capita gross domestic product, the percentage of the countrys economy that is industrialized, market capital as a percentage of gross domestic product, the overall regulatory environment, the presence of government regulation limiting or banning foreign ownership, and restrictions on repatriation of initial capital, dividends, interest and/or capital gains, and may also consider whether the country is designated as a developed market by MSCI Inc. When assessed along these criteria, a developed country will generally resemble the United States and European Union countries more closely relative to developing countries. In addition, under normal market conditions, the fund invests at least 35% of its assets in equity and debt securities of issuers domiciled in qualified developing countries. For purposes of this investment strategy, a qualified developing country will generally resemble the United States and European Union countries more closely relative to nonqualified developing countries. The funds investment adviser maintains a list of qualified developing countries and securities in which the fund may invest. As of December 1, 2025, the qualified developing countries for purposes of the funds investment strategy include Argentina, Bahrain, Bangladesh, Barbados, Belarus, Belize, Bolivia, Botswana, Brazil, Bulgaria, Chile, China, Colombia, Costa Rica, Croatia, Czech Republic, Dominican Republic, Ecuador, Egypt, El Salvador, Estonia, Gabon, Ghana, Greece, Hungary, India, Indonesia, Iraq, Jamaica, Jordan, Kazakhstan, Kenya, Kuwait, Latvia, Lebanon, Lithuania, Malaysia, Maldives, Mauritius, Mexico, Montenegro, Morocco, Namibia, Oman, Pakistan, Panama, Paraguay, Peru, Philippines, Poland, Qatar, Romania, Russia, Saudi Arabia, Serbia, Slovakia, South Africa, Sri Lanka, Thailand, Trinidad and Tobago, Tunisia, Turkey, Ukraine, United Arab Emirates, Uruguay, Venezuela, Vietnam and Zambia. It is possible that the fund may not have investments in one or more of these countries at any given time. The fund may also invest in debt securities of issuers, including issuers of lower rated bonds (rated Ba1 or below and BB+ or below by Nationally Recognized Statistical Rating Organizations designated by the funds investment adviser or unrated but determined to be of equivalent quality by the funds investment adviser), with exposure to these countries. Bonds rated Ba1 or BB+ or below are sometimes referred to as junk bonds. In addition, the fund may invest in nonconvertible debt securities of issuers, including issuers of lower rated bonds and government bonds, that are primarily based in qualified countries or that have a significant portion of their assets or revenues attributable to developing countries. The investment adviser uses a system of multiple portfolio managers in managing the fund’s assets. Under this approach, the portfolio of the fund is divided into segments managed by individual managers. The fund relies on the professional judgment of its investment adviser to make decisions about the funds portfolio investments. The basic investment philosophy of the investment adviser is to seek to invest in attractively valued companies that, in its opinion, represent good, long-term investment opportunities. Securities may be sold when the investment adviser believes that they no longer represent relatively attractive investment opportunities.', '0000051931-25-001491', 'S000009633', '2025-12-31'
FROM funds WHERE ticker = 'RNWGX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- RTRIX: accession 0000949377-26-000014, series S000009510, prospectus date 2026-04-30
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Royce Small-Cap Total Return Funds investment goals are long-term growth of capital and current income.', 'Royce Investment Partners (Royce), the Fund’s investment adviser, invests the Fund’s assets primarily in dividend-paying equity securities of small-cap companies that it believes are trading below its estimate of their current worth. Small-cap companies are those that have a market capitalization not greater than that of the largest company in the Russell 2000 Index at the time of its most recent reconstitution. Royce believes that regular dividend payments, and/or other methods of returning capital to shareholders such as issuer share repurchases, are often a positive signal that may indicate attractive attributes, including a stable business model, shareholder-friendly management, disciplined capital allocation practices, and a conservative financial culture. The Fund seeks to achieve its investment objectives by primarily investing in companies that pay regular dividends and/or return capital to shareholders. Royce favors companies that fall into one of three investment themes: Compounder companies possess what Royce believes are outstanding business models, strong financial characteristics, and above-average growth potential. Quality Value companies have attractive profit margins, strong free cash flows, high returns on invested capital, and low leverage that also trade at what Royce believes are attractive valuations. Special Situations are companies that may have complex business models and/or require a catalyst for growth, such as spin offs, turnarounds, and/or unrecognized asset values. The Fund invests at least 65% of its net assets in dividend-paying equity securities, under normal circumstances. In addition, the Fund invests at least 80% of its net assets in equity securities of small-cap companies, under normal circumstances. Although the Fund generally focuses on securities of U.S. companies, it may invest up to 25% of its net assets (measured at the time of investment) in equity securities of companies headquartered in foreign countries. The Fund may invest in other investment companies that invest primarily in equity securities. The Fund may sell securities to, among other things, secure gains, limit losses, redeploy assets into what Royce deems to be more promising opportunities, and/or manage cash levels in the Fund’s portfolio.', '0000949377-26-000014', 'S000009510', '2026-04-30'
FROM funds WHERE ticker = 'RTRIX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- TGEPX: accession 0001193125-26-081516, series S000006338, prospectus date 2025-10-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Fund’s investment objective is to seek high total return from current income and capital appreciation.', 'Under normal circumstances, the Fund invests at least 80% of the value of its net assets, plus any borrowings for investment purposes, in debt securities issued or guaranteed by companies, financial institutions and government entities in Emerging Market Countries (as defined in the paragraph below). If the Fund changes this investment policy, it will notify shareholders in writing at least 60 days in advance of the change. The Fund may invest in high yield or below investment grade bonds (commonly known as junk bonds), which are bonds rated below BBB by S&P Global Ratings or below Baa by Moodys Investors Service, Inc., or, if unrated, bonds deemed by the Fund’s investment advisor to be of comparable quality. The Fund generally invests in at least four Emerging Market Countries. An Emerging Market Country means any of the countries in the J.P. Morgan Emerging Market Bond Index (EMBI) Global Diversified, the J.P. Morgan Corporate Emerging Market Bond Index (CEMBI) Broad Diversified, the J.P. Morgan Government Bond Index-Emerging Markets (GBI-EM), the MSCI Total Return Emerging Markets Index (Net) and the MSCI Frontier Markets Index. Emerging Markets corporate debt includes the debt of companies in each of these indices and debt of companies in the countries that are in each of these indices. The Fund may invest in distressed or defaulted corporate securities where the portfolio managers believe the restructured enterprise valuations or liquidation valuations may significantly exceed current market values. In addition, the Fund may invest in distressed or defaulted sovereign investments where the portfolio managers believe the expected debt sustainability of the country exceeds current market valuations. The Fund may invest in derivative instruments, such as credit-linked notes, structured investments, options, futures, options on futures (including those related to options, securities, foreign currencies, indexes and interest rates), forward contracts, swaps (including interest rate and credit default swaps) and options on swaps, for investment management ( e.g. , as a substitute for investing directly in debt securities and currencies, to increase returns, to manage credit or interest rate risk, or to manage the effective maturity or duration of the Fund’s investment portfolio) or hedging purposes. The Fund also may make forward commitments in which the Fund agrees to buy or sell a security in the future at a price agreed upon today. In allocating investments among various Emerging Market Countries, the portfolio managers attempt to analyze internal political, market and economic factors. These factors include, but are not limited to: Public finances; Monetary policy; External accounts; Financial markets; Foreign investment regulations; Exchange rate policy; Labor conditions; Political outlook; Structural reform policy; and ESG factors. Portfolio securities and other instruments may be sold for a number of reasons, including when the portfolio managers believe that (i) an individual security or instrument has reached its sell target, (ii) there has been a deterioration in the credit fundamentals of an issuer, (iii) there are negative macroeconomic or geopolitical considerations that may affect an issuer, (iv) another security or instrument may offer a better investment opportunity, or (v) the portfolio should be rebalanced for diversification or portfolio weighting purposes.', '0001193125-26-081516', 'S000006338', '2025-10-31'
FROM funds WHERE ticker = 'TGEPX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- VADFX: accession 0001104659-25-122485, series S000027817, prospectus date 2025-12-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Fund’s investment objective is total return through growth of capital and current income.', 'The Fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in common stocks of companies represented in the S&P 500 Equal Weight Index (the Underlying Index), and in derivatives and other instruments that have economic characteristics similar to such securities. The Fund generally invests, under normal circumstances, all, or substantially all, of its net assets in such securities. The Underlying Index is an equal-weighted version of the S&P 500 Index, which is comprised of common stocks of approximately 500 large-capitalization companies that generally represent the large-cap segment of the U.S. equity market. Equal weighting means that, unlike the S&P 500 Index, which employs a float-adjusted market capitalization weighted methodology, the Underlying Index assigns each component security the same weight at each quarterly rebalance. In seeking to track the investment results (before fees and expenses) of the Underlying Index, the portfolio managers primarily utilize a full replication methodology, pursuant to which the Fund generally invests in all of the securities comprising the Underlying Index in proportion to their weightings in the Underlying Index. The Underlying Index is typically rebalanced quarterly and constituent changes are incorporated in the Underlying Index as and when they are made to the S&P 500 Index. The Fund is generally rebalanced in accordance with the Underlying Index. Constituent changes are generally incorporated in the Fund as and when they are made to the Underlying Index. The Fund can invest in derivative instruments including futures contracts. The Fund can use futures contracts, including index futures, to seek exposure to certain equity securities represented in the Underlying Index while managing cash balances.', '0001104659-25-122485', 'S000027817', '2025-12-31'
FROM funds WHERE ticker = 'VADFX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- VFWAX: accession 0001193125-26-077485, series S000015871, prospectus date 2025-10-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Vanguard FTSE All-World ex-US ETF, an exchange-traded share class of Vanguard FTSE All-World ex-US Index Fund (the Fund), seeks to track the performance of a benchmark index that measures the investment return of stocks of companies located in developed and emerging markets outside of the United States.', 'The Fund employs an indexing investment approach designed to track the performance of the FTSE All-World ex US Index (the Target Index), a float-adjusted, market-capitalization weighted index designed to measure equity market performance of large- and mid-cap stocks in international developed and emerging markets, excluding the United States. Under normal circumstances, the Fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in the stocks that make up the Target Index. The Fund attempts to replicate the Target Index by investing all, or substantially all, of its assets in the stocks that make up the Target Index, holding each stock in approximately the same proportion as its weighting in the Target Index.', '0001193125-26-077485', 'S000015871', '2025-10-31'
FROM funds WHERE ticker = 'VFWAX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- VWIGX: accession 0001193125-25-325146, series S000004453, prospectus date 2025-08-31
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'Vanguard International Growth Fund (the Fund) seeks to provide long-term capital appreciation.', 'The Fund employs an active management approach, investing mainly in stocks of companies located outside the United States. The Fund is expected to diversify its assets in countries across developed and emerging markets. In selecting stocks, the Fund’s advisors evaluate foreign markets around the world and choose large-, mid-, and small-capitalization companies considered to have above-average growth potential. The Fund has multiple investment advisors, each of which independently selects and maintains a portfolio of common stocks for the Fund.', '0001193125-25-325146', 'S000004453', '2025-08-31'
FROM funds WHERE ticker = 'VWIGX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- WEGRX: accession 0001081400-25-000422, series S000015703, prospectus date 2025-04-30
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Fund seeks long-term capital appreciation.', 'Under normal circumstances, we invest: at least 80% of the Fund’s total assets in equity securities of small-capitalization companies; and up to 25% of the Fund’s total assets in equity securities of foreign issuers through American Depository Receipts (ADRs) and similar investments. We invest principally in equity securities of small-capitalization companies, which we define as companies with market capitalizations within the range of the Russell 2000 Index at the time of purchase. The market capitalization range of the Russell 2000 Index was approximately $2.13 million to $19.09 billion, as of July 31, 2025, and is expected to change frequently. Small-capitalization companies may include both domestic and foreign small-capitalization companies. We seek small-capitalization companies that are in the emerging phase of their life cycle. We believe earnings and revenue growth relative to consensus expectations are critical factors in determining stock price movements. Thus, our investment process focuses on identifying companies with robust and sustainable growth in revenue and earnings that are underappreciated by the market. To find that growth, we use bottom-up research, emphasizing companies whose management teams have a history of successfully executing their strategy and whose business model have sufficient profit potential. We forecast revenue and earnings growth along with other key financial metrics to assess investment potential. We then combine that company-specific analysis with our assessment of what the market is discounting for growth to form a buy/sell decision about a particular stock. We seek to capitalize on investment opportunities where a sizable gap exists between market consensus and our expectation for a company’s growth prospects. We may invest in any sector and, at times, we may emphasize one or more particular sectors. In addition, our investment process is built on a foundation of continuous risk management and a strict sell discipline. We sell a company’s securities when we see signs that can cause a company’s growth prospects to deteriorate, as this often leads to lower valuation potential. We may also sell or trim a position when we need to raise money to fund the purchase of a better investment opportunity or when valuation has extended beyond our expectations.', '0001081400-25-000422', 'S000015703', '2025-04-30'
FROM funds WHERE ticker = 'WEGRX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- WFPRX: accession 0001081400-26-000048, series S000007349, prospectus date 2025-09-30
INSERT INTO fund_descriptions (fund_id, objective_text, strategies_text, source_accession, source_series_id, filing_ddate)
SELECT id, 'The Fund seeks long-term capital appreciation.', 'Under normal circumstances, we invest: at least 80% of the Fund’s net assets in equity securities of medium-capitalization companies. We invest principally in equity securities of medium-capitalization companies, which we define as securities of companies with market capitalizations within the range of the Russell Midcap Index at the time of purchase. The market capitalization range of the Russell Midcap Index was approximately $ 1.03 billion to $ 101.64 billion, as of December 31, 2025, and is expected to change frequently. We look for undervalued companies that we believe have the potential for above average capital appreciation with below average risk. Rigorous fundamental research drives our search for companies with favorable reward-to-risk ratios and that possess, a long-term competitive advantage provided by a durable asset base, strong balance sheets, and sustainable and superior cash flows. Typical investments include stocks of companies that are generally out of favor in the marketplace, or are undergoing reorganization or other corporate action that may create above-average price appreciation. We regularly review the investments of the portfolio and may sell a portfolio holding when a stock nears its price target, downside risks increase considerably, the company’s fundamentals have deteriorated, or we identify a more attractive investment opportunity.', '0001081400-26-000048', 'S000007349', '2025-09-30'
FROM funds WHERE ticker = 'WFPRX'
ON CONFLICT (fund_id) DO UPDATE SET objective_text = EXCLUDED.objective_text, strategies_text = EXCLUDED.strategies_text, source_accession = EXCLUDED.source_accession, source_series_id = EXCLUDED.source_series_id, filing_ddate = EXCLUDED.filing_ddate, ingested_at = now();

-- ── Verify (expect: 23, zero missing, 23 rows with both texts) ──
SELECT count(*) AS rows_seeded FROM fund_descriptions;
SELECT f.ticker FROM funds f LEFT JOIN fund_descriptions fd ON fd.fund_id = f.id WHERE f.is_active AND fd.fund_id IS NULL;
SELECT f.ticker, length(fd.objective_text) AS obj_chars, length(fd.strategies_text) AS strat_chars, fd.filing_ddate FROM fund_descriptions fd JOIN funds f ON f.id = fd.fund_id ORDER BY f.ticker;